%AE31 could be homogenised with AE33:
% common period= 1.8.1997 - 9.12.2001
Pt=timerange('2023-01-01','2023-04-12');
ratio_med_h=nanmedian(OPE_rd.Ba3_A(Pt)./OPE_rd.Ba31_A(Pt)) %0.8427
ratio_STN_h=nanstd(OPE_rd.Ba3_A(Pt)./OPE_rd.Ba31_A(Pt)) %     0.0972 
ratio_mean_h=nanmean(OPE_rd.Ba3_A(Pt)./OPE_rd.Ba31_A(Pt)) %     0.8556
ratio_mean=nanmean(OPE_rd.Ba3_A(Pt))/nanmean(OPE_rd.Ba31_A(Pt)) %     0.8422
ratio_median=nanmedian(OPE_rd.Ba3_A(Pt))/nanmedian(OPE_rd.Ba31_A(Pt)) %     0.8648
figure; %[output:192d87f4]
plot(OPE_rd.Ba3_A(Pt),OPE_rd.Ba31_A(Pt),'.'); %[output:192d87f4]

% fit between both data: slope 1.297x-0.157, inverse= 0.7710
fit_test=robustfit(OPE_rd.Ba3_A(Pt),OPE_rd.Ba31_A(Pt)); % y coor=-0.1116, slope=1.2676, 1/slope=0.7889

cte_AE31_AE33=1.20;
%%
